import React from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import Layout from './components/Layout';
import Home from './pages/Home';
import Browse from './pages/Browse';
import ProductDetails from './pages/ProductDetails';
import Checkout from './pages/Checkout';
import UserAuth from './pages/UserAuth';
import AdminLogin from './pages/AdminLogin';
import AdminDashboard from './pages/AdminDashboard';
import AdminEditAccount from './pages/AdminEditAccount';
import UserDashboard from './pages/UserDashboard';

const App: React.FC = () => {
  return (
    <HashRouter>
      <Layout>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/browse" element={<Browse />} />
          <Route path="/account/:id" element={<ProductDetails />} />
          <Route path="/checkout" element={<Checkout />} />
          <Route path="/login" element={<UserAuth />} />
          <Route path="/dashboard" element={<UserDashboard />} />
          <Route path="/admin" element={<AdminLogin />} />
          <Route path="/admin/dashboard" element={<AdminDashboard />} />
          <Route path="/admin/edit/:id" element={<AdminEditAccount />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { UserCog, Home, Gamepad2, User as UserIcon, LogOut, LayoutDashboard, Zap, Award, Sparkles, X, Trophy } from 'lucide-react';
import { StorageService, DEFAULT_HOME_CONFIG, SITE_LOGO_URL } from '../services/storage';
import { User, HomeConfig } from '../types';
import SkinSearchFloatingBar from './SkinSearchFloatingBar';

const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  const [showBonusPopup, setShowBonusPopup] = useState(false);
  const [prevPoints, setPrevPoints] = useState<number | null>(null);
  const [pointDiff, setPointDiff] = useState<number | null>(null);
  const [homeConfig, setHomeConfig] = useState<HomeConfig>(DEFAULT_HOME_CONFIG);

  const isHomePage = location.pathname === '/';

  // SCROLL TO TOP LOGIC
  useEffect(() => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  }, [location.pathname]);

  const loadConfig = async () => {
    try {
      const config = await StorageService.getHomeConfig();
      setHomeConfig(config);
    } catch (err) {}
  };

  const syncData = () => {
    const user = StorageService.getCurrentUser();

    // Animate point changes
    if (user && prevPoints !== null && user.ultraPoints > prevPoints) {
      const diff = user.ultraPoints - prevPoints;
      setPointDiff(diff);
      setTimeout(() => setPointDiff(null), 4000);
    }

    setCurrentUser(user);
    if (user) setPrevPoints(user.ultraPoints);

    loadConfig();

    // Show bonus popup if user has exactly 20 points (newly registered) and hasn't seen it this session
    if (user && user.ultraPoints === 20 && !sessionStorage.getItem('bonus_shown')) {
      setShowBonusPopup(true);
      sessionStorage.setItem('bonus_shown', 'true');
    }
  };

  useEffect(() => {
    syncData();
    // Run expiration check immediately on load
    StorageService.checkExpiredBookings();

    // Set up interval to check for expired bookings every minute
    const expiryInterval = setInterval(() => {
        StorageService.checkExpiredBookings();
    }, 60000);

    const unsubscribe = StorageService.subscribe(() => {
      syncData();
    });
    window.addEventListener('storage', syncData);
    return () => {
      clearInterval(expiryInterval);
      unsubscribe();
      window.removeEventListener('storage', syncData);
    };
  }, [location.pathname]);

  const handleLogout = () => {
    StorageService.logoutUser();
    setCurrentUser(null);
    setShowProfileMenu(false);
    navigate('/');
  };

  const isActive = (path: string) => location.pathname === path ? 'text-brand-accent drop-shadow-[0_0_8px_rgba(255,70,85,0.8)] border-b-2 border-brand-accent' : 'text-slate-400 hover:text-white hover:drop-shadow-[0_0_5px_rgba(255,255,255,0.5)]';

  const isTabActive = (path: string) => {
    if (path === '/') return location.pathname === '/';
    return location.pathname.startsWith(path);
  };

  return (
    <div className="min-h-screen bg-brand-darker text-slate-100 font-sans flex flex-col selection:bg-brand-accent selection:text-white relative">

      {/* Point Earned Floating Animation */}
      {pointDiff !== null && (
        <div className="fixed top-24 right-4 md:right-12 z-[100] pointer-events-none animate-in fade-in slide-in-from-bottom-4 duration-700">
           <div className="flex items-center gap-2 bg-yellow-500/20 backdrop-blur-md border border-yellow-500/50 px-4 py-2 rounded-full shadow-[0_0_30px_rgba(234,179,8,0.4)]">
              <Sparkles className="text-yellow-400 w-5 h-5 animate-spin-slow" />
              <span className="text-yellow-400 font-black text-xl">+{pointDiff} UP</span>
           </div>
        </div>
      )}

      {/* Bonus Popup */}
      {showBonusPopup && (
         <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-brand-surface border border-yellow-500/30 rounded-2xl p-8 max-w-sm relative text-center shadow-[0_0_50px_rgba(234,179,8,0.2)]">
               <button onClick={() => setShowBonusPopup(false)} className="absolute top-4 right-4 text-slate-500 hover:text-white"><X size={20} /></button>
               <div className="w-20 h-20 bg-yellow-500/20 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce">
                  <Award size={40} className="text-yellow-500" />
               </div>
               <h3 className="text-2xl font-black text-white italic uppercase mb-2">Welcome Bonus!</h3>
               <p className="text-slate-400 mb-6">You've received <span className="text-yellow-500 font-bold">20 Ultra Points</span> for joining the elite.</p>
               <button onClick={() => setShowBonusPopup(false)} className="w-full py-3 bg-yellow-500 hover:bg-yellow-400 text-brand-darker font-black uppercase tracking-widest rounded-lg">Claim Reward</button>
            </div>
         </div>
      )}

      {/* Navigation Bar */}
      <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${location.pathname === '/' && window.scrollY < 50 ? 'bg-transparent py-6' : 'bg-brand-darker/80 backdrop-blur-lg border-b border-white/5 py-4'}`}>
        <div className="max-w-7xl mx-auto px-4 flex items-center justify-between">
           <Link to="/" className="flex items-center gap-3 group">
              <img src={SITE_LOGO_URL} alt="Krishna Valo" className="w-8 h-8 md:w-10 md:h-10 object-contain group-hover:drop-shadow-[0_0_15px_rgba(255,70,85,0.5)] transition-all" />
              <div className="hidden md:block">
                 <h1 className="font-display font-black text-lg md:text-xl tracking-wide uppercase italic leading-none text-white">Krishna <span className="text-brand-accent">Valo</span></h1>
                 <p className="text-[9px] text-slate-400 font-mono tracking-[0.3em] uppercase">Premium Rentals</p>
              </div>
           </Link>

           {/* Center - Skin Search (Floating logic handled by component) */}
           <SkinSearchFloatingBar isHomePage={isHomePage} />

           <div className="flex items-center gap-6">
              <nav className="hidden md:flex items-center gap-6 text-sm font-bold uppercase tracking-widest">
                 <Link to="/" className={isActive('/')}>Home</Link>
                 <Link to="/browse" className={isActive('/browse')}>Inventory</Link>
              </nav>

              {currentUser ? (
                <div className="relative">
                   <button onClick={() => setShowProfileMenu(!showProfileMenu)} className="flex items-center gap-3 hover:bg-white/5 px-2 py-1.5 rounded-lg transition-colors border border-transparent hover:border-white/10">
                      <div className="text-right hidden sm:block">
                         <div className="text-xs font-bold text-white">{currentUser.name}</div>
                         <div className="text-[9px] text-yellow-500 font-mono">{currentUser.ultraPoints} UP</div>
                      </div>
                      <img src={currentUser.avatarUrl} alt="" className="w-8 h-8 rounded bg-brand-surface object-cover border border-white/10" />
                   </button>

                   {showProfileMenu && (
                     <>
                     <div className="fixed inset-0 z-40" onClick={() => setShowProfileMenu(false)}></div>
                     <div className="absolute right-0 top-full mt-2 w-56 bg-brand-surface border border-white/10 rounded-xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2">
                        <div className="p-4 border-b border-white/5 bg-brand-dark/50">
                           <div className="font-bold text-white truncate">{currentUser.name}</div>
                           <div className="text-xs text-slate-500 truncate">{currentUser.email}</div>
                        </div>
                        <div className="p-2">
                           {currentUser.role === 'admin' && (
                             <Link to="/admin/dashboard" onClick={() => setShowProfileMenu(false)} className="flex items-center gap-3 px-3 py-2 text-sm text-slate-300 hover:text-white hover:bg-white/5 rounded-lg">
                                <UserCog size={16} /> Admin Panel
                             </Link>
                           )}
                           <Link to="/dashboard" onClick={() => setShowProfileMenu(false)} className="flex items-center gap-3 px-3 py-2 text-sm text-slate-300 hover:text-white hover:bg-white/5 rounded-lg">
                              <LayoutDashboard size={16} /> Dashboard
                           </Link>
                           <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-2 text-sm text-red-400 hover:bg-red-500/10 rounded-lg text-left">
                              <LogOut size={16} /> Logout
                           </button>
                        </div>
                     </div>
                     </>
                   )}
                </div>
              ) : (
                <Link to="/login" className="px-6 py-2 bg-white text-brand-darker font-black text-xs uppercase tracking-widest rounded skew-x-[-10deg] hover:bg-brand-accent hover:text-white transition-all hover:scale-105 shadow-[0_0_20px_rgba(255,255,255,0.2)]">
                   <div className="skew-x-[10deg]">Login</div>
                </Link>
              )}
           </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 pt-20 md:pt-24">
         {children}
      </main>

      {/* Footer */}
      <footer className="bg-black border-t border-white/5 pt-16 pb-8 relative overflow-hidden">
         <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-brand-accent/50 to-transparent"></div>
         <div className="max-w-7xl mx-auto px-4">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-12 mb-12">
               <div className="col-span-1 md:col-span-2">
                  <Link to="/" className="flex items-center gap-3 mb-6">
                     <img src={SITE_LOGO_URL} alt="" className="w-8 h-8 opacity-80 grayscale" />
                     <span className="font-display font-black text-xl text-white uppercase italic tracking-wide">Krishna <span className="text-brand-accent">Valo</span></span>
                  </Link>
                  <p className="text-slate-500 text-sm leading-relaxed max-w-sm mb-6">
                     India's premier Valorant account rental platform. Verified skins, ranked ready, and instant delivery via automated protocols.
                  </p>
                  <div className="flex gap-4">
                     <a href="#" className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-slate-400 hover:bg-brand-accent hover:text-white transition-all"><Gamepad2 size={18} /></a>
                     <a href="#" className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-slate-400 hover:bg-brand-cyan hover:text-brand-dark transition-all"><Trophy size={18} /></a>
                  </div>
               </div>

               <div>
                  <h4 className="text-white font-bold uppercase tracking-widest text-xs mb-6">Navigation</h4>
                  <ul className="space-y-3 text-sm text-slate-500">
                     <li><Link to="/" className="hover:text-brand-accent transition-colors">Home Base</Link></li>
                     <li><Link to="/browse" className="hover:text-brand-accent transition-colors">Inventory</Link></li>
                     <li><Link to="/login" className="hover:text-brand-accent transition-colors">Agent Login</Link></li>
                     <li><Link to="/dashboard" className="hover:text-brand-accent transition-colors">Dashboard</Link></li>
                  </ul>
               </div>

               <div>
                  <h4 className="text-white font-bold uppercase tracking-widest text-xs mb-6">Legal</h4>
                  <ul className="space-y-3 text-sm text-slate-500">
                     <li><a href="#" className="hover:text-brand-accent transition-colors">Terms of Service</a></li>
                     <li><a href="#" className="hover:text-brand-accent transition-colors">Privacy Policy</a></li>
                     <li><a href="#" className="hover:text-brand-accent transition-colors">Refund Policy</a></li>
                     <li><a href="#" className="hover:text-brand-accent transition-colors">Support</a></li>
                  </ul>
               </div>
            </div>

            <div className="pt-8 border-t border-white/5 flex flex-col md:flex-row justify-between items-center gap-4">
               <div className="text-[10px] text-slate-600 font-mono uppercase tracking-widest">
                  © 2024 Krishna Valo Store. All Rights Reserved.
               </div>
               <div className="flex items-center gap-2 text-[10px] text-slate-600 font-mono uppercase tracking-widest">
                  <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
                  System Operational
               </div>
            </div>
         </div>
      </footer>
    </div>
  );
};

export default Layout;
